const root=document.querySelector('#portal-root'),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₹'+new Intl.NumberFormat('en-IN').format(n||0),date=v=>new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'});
let catalog=await fetch('/studio/catalog.json').then(r=>r.json()),session={user:null,admin:false},workspace={records:[],bookings:[],rewards:[]},draft,activeBuild=null,frame=null,studioReady=false,heroStop=null,profileTab='builds',adminTab='enquiries',selected=new Set(),snapshots=[],view='home',quality=localStorage.getItem('cd-quality')||'balanced',draftRecord=null,autosaveTimer,autosaveQueue=Promise.resolve(),gameRun=null,gameQueue=Promise.resolve(),currentRouteToken=0;
try{const s=JSON.parse(localStorage.getItem('cd-platform-draft')||localStorage.getItem('cd-build-v3')||'null');if(s&&Array.isArray(s.addons)&&s.addons.length===3&&s.addons.includes('awning')&&s.addons.includes('extraSolar')&&s.addons.includes('outdoorLights')&&!s.title)s.addons=[];draft=normalize(s||defaults,catalog)}catch{draft=normalize(defaults,catalog)}
const toastNode=document.createElement('div');toastNode.className='portal-toast';toastNode.hidden=true;toastNode.setAttribute('role','status');document.body.append(toastNode);
function toast(t){toastNode.textContent=t;toastNode.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastNode.hidden=true,4500)}
const btn=(text,act,kind='')=>`<button class="btn ${kind}" data-act="${act}">${text}</button>`;
const empty=(text,action='')=>`<div class="empty">${text}${action?'<div class="actions" style="justify-content:center;margin-top:20px">'+action+'</div>':''}</div>`;
