const recordById=id=>workspace.records.find(r=>r.id===id);
function header(){return `<header class="portal-nav"><a href="#home" class="portal-brand" aria-label="Camper Dynamics home"><svg viewBox="0 0 52 32"><path d="M2 27 17 13 24 20 33 4 49 26M17 13 20 24M33 4 35 20"/></svg><span>CAMPER<br>DYNAMICS<small>EXPLORE · BUILD · BELONG</small></span></a><nav class="portal-links" aria-label="Main navigation">${[['home','Home'],['build','3D Build'],['book','Book'],['game','Game'],['profile','Profile']].map(([id,label])=>`<a href="#${id}" class="${view===id?'active':''}">${label}</a>`).join('')}</nav><span class="portal-status">YOUR NEXT CHAPTER STARTS HERE</span></header>${isPreview?'<div class="preview-banner">DEVICE PREVIEW · Workspace and admin actions here stay on this device. Hosted accounts use the server database.</div>':''}`;}
function footer(){return `<footer class="portal-footer"><span>Camper Dynamics · Made for the long way home.</span><div><a href="#book">Book a conversation</a><a href="#profile">Your workspace</a>${session.admin?'<a href="#admin">Administration</a>':''}</div><span>Illustrative vehicle, layouts and prices · Final specification by approval.</span></footer>`;}
function modal(title,html){$('#portal-dialog')?.remove();const d=document.createElement('dialog');d.id='portal-dialog';d.className='portal-modal';d.innerHTML=`<div class="modal-head"><span class="eyebrow">${esc(title)}</span><button class="close-modal" aria-label="Close dialog" data-act="close">×</button></div><div class="modal-body">${html}</div>`;root.append(d);d.showModal();return d;}
function close(){ $('#portal-dialog')?.close();}
function send(type,data={}){frame?.contentWindow?.postMessage({type,...data},location.origin)}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
async function refresh(){workspace=await api('/workspace'+(view==='admin'?'?admin=1':''));if(!workspace.records)workspace={records:[],bookings:[],rewards:[]};draftRecord=byKind('draft')[0]||null;}
async function render(){const token=++currentRouteToken;heroStop?.();heroStop=null;const route=location.hash.slice(1)||'home';view=route.startsWith('share/')?'share':route;document.body.classList.toggle('workspace-view',['build','game'].includes(view));if(!['home','build','book','game','profile','admin','share'].includes(view))view='home';frame=null;studioReady=false;root.innerHTML=header()+`<main id="portal-view" class="portal-page"><div class="loading">Loading your workspace…</div></main>`+footer();window.scrollTo(0,0);try{
 if(['profile','admin','share','book'].includes(view)&&session.user)await refresh();if(token!==currentRouteToken)return;
 if(view==='home')await home();if(view==='build')build();if(view==='game')game();if(view==='book')await bookingPage();if(view==='profile')profile();if(view==='admin')await admin();if(view==='share')await sharedPage(route.split('/')[1]);
 }catch(e){$('#portal-view').innerHTML=`<div class="portal-container"><div class="error-box">${esc(e.message)}</div></div>`;}}
function home(){ $('#portal-view').innerHTML=`<section class="hero-story"><div class="hero-sticky"><div id="hero-model" class="hero-model" aria-label="Interactive camper showcase"></div><div class="hero-gradient"></div><div class="hero-copy"><p class="eyebrow" id="hero-kicker">THE HILUX BASECAMP / 01</p><h1 id="hero-title">Your pickup.<br>A bigger life.</h1><p class="lead" id="hero-text">A home beyond the everyday. Explore a removable camper, made around the way you travel.</p><div class="actions"><a class="btn" href="#build">Build your escape <span>↗</span></a>${btn('Find my starting point','wizard','secondary')}</div></div><div class="scroll-hint">SCROLL TO EXPLORE ↓</div><div class="hero-chapters"><div class="chapter-links">${['Discover','Assembly','Exterior','Above','Inside','After dark'].map((t,i)=>`<button data-act="chapter:${i}" class="${i===0?'active':''}">0${i+1} / ${t}</button>`).join('')}</div><div class="hero-spec">HILUX + BASECAMP<br>INTERACTIVE DESIGN CONCEPT</div></div></div></section><section class="feature-section contact-section" id="contact"><p class="eyebrow">LET’S BUILD YOUR NEXT CHAPTER</p><div class="editorial-grid"><div><h2>Tell us where<br>you want to wake up.</h2><p class="lead">Tell us about your vehicle, your plans and the space you imagine. Start a conversation around your own camper.</p><div class="actions"><a class="btn" href="#build">Customise my camper ↗</a><a class="btn secondary" href="#game">Try a virtual ride ↗</a></div></div><form id="contact-form" class="portal-form portal-card"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email<input name="email" type="email" required maxlength="150" autocomplete="email"></label><label>Your plans<textarea name="message" required maxlength="2000" placeholder="Your vehicle, where you travel, your ideal camper…"></textarea></label><label class="check-label"><input type="checkbox" name="includeBuild" checked><span>Include my chosen finish and configuration.</span></label><label class="check-label"><input type="checkbox" required><span>I agree to store these details with my enquiry.</span></label><button class="btn">Start the conversation ↗</button><output id="contact-result" role="status"></output></form></div></section>`;const stopStory=startShowcase($('#hero-model'),draft,catalog,id=>setDraft({...draft,color:id}));heroStop=stopStory;$('#contact-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{requireAccount();const contact=Object.fromEntries(new FormData(e.currentTarget));const r=await api('/records',{method:'POST',body:{kind:'enquiry',title:contact.name+' · Website enquiry',data:{...configData(contact.includeBuild?draft:defaults),contact,includeBuild:!!contact.includeBuild}}});$('#contact-result').textContent='Enquiry saved. Reference '+r.id.slice(0,8).toUpperCase()+'. Follow up or book a consultation through your workspace. No email has been sent.';e.target.reset()}catch(err){toast(err.message)}finally{button.disabled=false}};api('/faq').then(f=>{const section=$('#contact');if(section)for(const x of f.items||[])section.insertAdjacentHTML('beforeend',`<details class="faq"><summary>${esc(x.q)}</summary><p>${esc(x.a)}</p></details>`)}).catch(()=>{});}
function build(){ $('#portal-view').innerHTML=`<section class="studio-shell"><iframe class="studio-frame" id="studio-frame" src="/studio/index.html?embed=build" allow="fullscreen" allowfullscreen title="Camper 3D build studio"></iframe></section>`;frame=$('#studio-frame');}
function game(){ $('#portal-view').innerHTML=`<section class="game-shell"><iframe id="studio-frame" src="/studio/index.html?embed=game" allow="fullscreen" allowfullscreen title="Camper woodland game"></iframe></section>`;frame=$('#studio-frame');}
let deployed=false;
function recordCard(r){const cfg=r.data.config,p=r.data.estimate||cfg&&estimate(cfg,catalog);return `<article class="portal-card"><div class="record-top"><h3>${esc(r.title)}</h3><span class="chip">${r.kind==='proposal'?'SNAPSHOT':'V'+r.version}</span></div><p class="record-meta">${cfg?'Hilux + '+esc(catalog.models.find(x=>x.id===cfg.model)?.name)+' · '+esc(INTERIOR_THEMES[cfg.interior?.theme||'beige'].name):''}<br>${date(r.updated_at||r.created_at)}</p>${p?`<div class="record-price">${money(p.total)}<small style="font-size:10px;color:#9eb094"> conversion estimate</small></div>`:''}<div class="actions">${r.kind==='proposal'?btn('View proposal','viewProposal:'+r.id,'small'):btn('Open build','open:'+r.id,'small')}${r.kind==='build'?`${btn('History','history:'+r.id,'small secondary')}${btn('Discuss','discuss:'+r.id,'small secondary')}${btn('Share','share:'+r.id,'small secondary')}<label style="font-size:10px;color:#bfccaf"><input type="checkbox" data-compare="${r.id}" ${selected.has(r.id)?'checked':''}> Compare</label>`:''}</div></article>`;}
function profile(){if(!session.user){$('#portal-view').innerHTML=`<div class="portal-container">${empty('Sign in to keep builds, bookings and rewards across devices.','<a class="btn" href="/signin-with-chatgpt?return_to=%2F%23profile" target="_top">Continue with ChatGPT</a>')}</div>`;return;}const names={builds:'Saved builds',proposals:'Proposals',bookings:'Bookings',projects:'My project',rewards:'Trail & rewards',settings:'Preferences'};let content='';
 if(profileTab==='builds'){const builds=byKind('build');content=`<div class="actions" style="margin-bottom:20px">${btn('New build','new')}${btn('Compare selected (up to 3)','compare','secondary')}</div><div class="portal-grid">${builds.map(recordCard).join('')||empty('Your first escape is waiting. Save a build from the studio.')}</div>`;}
 if(profileTab==='proposals')content=`<div class="portal-grid">${byKind('proposal').map(recordCard).join('')||empty('Generate a proposal from your current build. Each version keeps its own configuration and estimate.',btn('Open studio','new','small'))}</div>`;
 if(profileTab==='bookings')content=workspace.bookings.map(bookingCard).join('')||empty('No appointments yet. Your selected configuration can accompany your consultation.','<a class="btn" href="#book">Book a conversation</a>');
 if(profileTab==='projects')content=byKind('project').map(projectCard).join('')||empty('No confirmed project has been created for this account. Project stages and photographs appear when the team adds them.');
 if(profileTab==='rewards'){const runs=byKind('run').filter(r=>r.data.complete);content=`<div class="portal-card"><div class="badge">✦</div><h2>${runs.length?'Woodland Explorer':'Your trail is waiting.'}</h2><p class="muted">${runs.length?runs.length+' completed run(s). Your progress is saved in this workspace.':'Complete all eight gates to earn the trail badge. Offers appear only when the team publishes approved terms.'}</p><a href="#game" class="btn">Take the trail</a></div><div class="records-list" style="margin-top:20px">${workspace.rewards.map(r=>`<article class="portal-card"><h3>${esc(r.code)}</h3><p class="muted">${esc(r.status)} · expires ${date(r.expires_at)}</p>${r.status==='issued'?btn('Redeem offer','redeem:'+r.code,'small'):''}</article>`).join('')}</div>`;}
 if(profileTab==='settings')content=`<div class="portal-card"><h2>Your preferences</h2><p class="muted">Account identity is managed through ChatGPT. Rendering preferences stay on this device.</p><label class="field">Rendering quality<select class="portal-input" id="profile-quality">${['high','balanced','low'].map(x=>`<option ${quality===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="notice">${isPreview?'Device preview data is stored locally.':'Builds, bookings, projects and rewards are stored against your signed-in account.'} Notifications are currently in-app. Email/SMS delivery is not connected.</p>${btn('Download my workspace','export','secondary')}${!isPreview?'<a class="btn secondary" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a>':''}</div>`;
 $('#portal-view').innerHTML=`<div class="portal-container"><div class="page-heading"><div><p class="eyebrow">YOUR NEXT CHAPTER</p><h1>A space for your escapes.</h1></div><a href="#build" class="btn secondary">Back to the studio ↗</a></div><div class="profile-columns"><aside class="profile-menu"><div class="profile-id"><strong>${esc(session.user.name)}</strong><small>${esc(session.user.email)}</small></div>${Object.entries(names).map(([id,n])=>`<button data-act="tab:${id}" class="${profileTab===id?'active':''}">${n}</button>`).join('')}${session.admin?'<a class="btn small secondary" href="#admin">Administration ↗</a>':''}</aside><div>${content}</div></div></div>`;$$('[data-compare]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.compare):selected.delete(el.dataset.compare);if(selected.size>3){selected.delete(el.dataset.compare);el.checked=false;toast('Compare up to three builds.')}});if($('#profile-quality'))$('#profile-quality').onchange=e=>{quality=e.target.value;localStorage.setItem('cd-quality',quality);toast('Rendering preference saved')};}
function bookingCard(b){return `<article class="portal-card" style="margin-bottom:16px"><div class="record-top"><h3>${esc(b.data.type||'Consultation')}</h3><span class="chip">${esc(b.status)}</span></div><p class="record-meta">${date(b.data.slot||b.slot)} IST<br>Reference ${b.id.slice(0,8).toUpperCase()} · ${esc(b.data.name)}<br>${esc(b.data.email)}<br>${b.data.buildId?'Build '+esc(b.data.buildId.slice(0,8)):'Configuration snapshot attached'}</p><p class="muted">${esc(b.data.notes||'')}</p>${(b.data.attachments||[]).length?`<div class="thumb-row">${b.data.attachments.map(id=>`<a href="${esc(fileURL(id))}" target="_blank" rel="noopener">${esc(recordById(id)?.title||'Private attachment')} ↗</a>`).join('')}</div>`:''}<div class="actions">${btn('View build','bookingBuild:'+b.id,'small secondary')}${btn('Calendar file','calendar:'+b.id,'small secondary')}${!['cancelled','completed'].includes(b.status)?btn('Reschedule','reschedule:'+b.id,'small secondary')+btn('Cancel','cancel:'+b.id,'small danger'):''}${view==='admin'&&b.status==='requested'?btn('Confirm request','confirm:'+b.id,'small'):''}</div></article>`;}
async function bookingPage(){const availability=await api('/availability');const builds=byKind('build');$('#portal-view').innerHTML=`<div class="portal-container"><div class="page-heading"><div><p class="eyebrow">LET’S MAKE IT YOURS</p><h1>Bring your next chapter to life.</h1><p class="lead">Book a conversation with your build attached. The team will confirm fitment, availability and the next steps.</p></div></div><div class="two-col"><div class="portal-card"><form id="booking-form" class="portal-form"><div class="form-row"><label>Your name<input required name="name" maxlength="100" autocomplete="name" value="${esc(session.user?.name||'')}"></label><label>Email<input required name="email" type="email" autocomplete="email" value="${esc(isPreview?'':session.user?.email||'')}"></label></div><div class="form-row"><label>Phone (optional)<input name="phone" type="tel" maxlength="30"></label><label>Conversation type<select name="type"><option>Consultation</option><option>Showroom visit</option><option>Fitment discussion</option></select></label></div><label>Attach a build<select name="buildId"><option value="">Current studio configuration</option>${builds.map(r=>`<option value="${r.id}" ${r.id===activeBuild?.id?'selected':''}>${esc(r.title)}</option>`).join('')}</select></label><div class="form-row"><label>Date<input id="book-date" name="date" type="date" required min="${new Date().toISOString().slice(0,10)}" max="${new Date(Date.now()+180*86400000).toISOString().slice(0,10)}"></label><label>Time · Asia/Kolkata<select id="book-time" name="time" required><option value="">Choose a date first</option></select></label></div><label>Your vehicle, travel plans and questions<textarea name="notes" maxlength="3000" placeholder="Vehicle model/year, number of travellers, intended trips…"></textarea></label><label>Vehicle photos or requirements<input id="book-files" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple><small class="muted">Up to five files; ${isPreview?'1 MB each in device preview':'4 MB each'}. Private to your workspace and authorised specialists.</small></label><label class="check-label"><input required name="consent" type="checkbox"><span>I agree to store these details and attachments with my consultation request.</span></label><button class="btn" type="submit">Request this appointment ↗</button><output id="booking-result"></output></form></div><aside><div class="portal-card"><p class="eyebrow">YOUR BUILD COMES WITH YOU</p><h2>Start with something tangible.</h2><div class="record-price">${money(estimate(draft,catalog).total)}</div><p class="muted">Hilux + ${esc(catalog.models.find(m=>m.id===draft.model)?.name)}<br>${esc(INTERIOR_THEMES[draft.interior.theme].name)}<br>${draft.addons.length} selected accessories</p><a href="#build" class="btn secondary">Review your configuration</a></div><div class="notice">A submitted request reserves this consultation time; the team confirms the appointment. Location or meeting details are supplied after confirmation. Email/SMS notifications are not connected.</div></aside></div></div>`;
 $('#book-date').onchange=()=>{const d=$('#book-date').value;$('#book-time').innerHTML='<option value="">Choose a time</option>'+availability.times.filter(t=>{const value=new Date(d+'T'+t+':00+05:30').toISOString();return new Date(value)>new Date(Date.now()+3600000)&&availability.days.includes(new Date(d+'T12:00:00+05:30').getDay())&&!availability.blocked.includes(d)&&!availability.occupied.includes(value)}).map(t=>`<option value="${t}">${t}</option>`).join('');};
 $('#booking-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type=submit]');submit.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(!data.time)throw Error('Choose an available time');const files=[...$('#book-files').files];if(files.length>5)throw Error('Choose at most five files');const attachments=[];for(const file of files){const f=new FormData();f.set('file',file);attachments.push((await api('/upload',{method:'POST',body:f})).id);}const b=await api('/bookings',{method:'POST',body:{...data,slot:new Date(data.date+'T'+data.time+':00+05:30').toISOString(),config:draft,consent:!!data.consent,attachments}});$('#booking-result').innerHTML=`<div class="notice">${isPreview?'Device preview request saved.':'Appointment request saved.'} Reference <strong>${b.id.slice(0,8).toUpperCase()}</strong>. Track confirmation in Profile.</div>`;form.reset();toast('Appointment request saved');}catch(err){$('#booking-result').textContent=err.message}finally{submit.disabled=false}};
}
function projectCard(r){const stages=['Requirements','Design approval','Production','Installation','Handover'],n=stages.indexOf(r.data.stage);return `<article class="portal-card" style="margin-bottom:20px"><h2>${esc(r.title)}</h2><p class="muted">Team-managed progress · ${esc(r.data.stage)}</p><div class="timeline">${stages.map((s,i)=>`<div class="${i<=n?'done':''}">${i+1}. ${s}<small>${i<n?'Reached':i===n?'Current':'Pending'}</small></div>`).join('')}</div>${(r.data.photos||[]).length?`<div class="thumb-row">${r.data.photos.map(p=>`<a href="${esc(fileURL(p))}" target="_blank" rel="noopener">Private project file ↗</a>`).join('')}</div>`:''}${(r.data.updates||[]).map(u=>`<div class="update"><span class="chip">${esc(u.stage)}</span><p>${esc(u.text)}</p><small class="muted">${date(u.at)}</small></div>`).join('')}${(r.data.approvals||[]).map(a=>`<p class="notice">Design revision ${a.designRevision||'legacy'} approved ${date(a.at)}</p>`).join('')}<div class="actions">${r.data.design?btn('Review design revision '+r.data.designRevision,'reviewDesign:'+r.id,'small secondary'):''}${r.data.stage==='Design approval'&&r.data.design&&r.user_id===session.user?.id&&!(r.data.approvals||[]).some(a=>a.designRevision===r.data.designRevision)?btn('Approve design revision '+r.data.designRevision,'approve:'+r.id,'small'):''}${r.data.stage==='Design approval'&&!r.data.design?'<p class="notice">A team member must post a design snapshot before approval.</p>':''}${view==='admin'?btn('Update project','projectUpdate:'+r.id,'small secondary'):''}</div></article>`;}

import {MOVABLE,ROOM,placement,validatePlacement} from '/studio/layout-config.js';
const configData=(config=draft)=>({config:structuredClone(config),estimate:estimate(config,catalog)});
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function requireAccount(){if(!session.user){go('profile');throw Error('Sign in to save this to your workspace.')}}
function setDraft(c){studioReady=false;draft=normalize(c,catalog);localStorage.setItem('cd-platform-draft',JSON.stringify(draft));send('CD_LOAD',{config:draft});}
function wizard(){modal('Find your starting point',`<h2>How will you travel?</h2><form id="wizard-form" class="portal-form"><label>Your travel style<select name="travel"><option value="weekend">Weekend escapes</option><option value="long">Longer journeys</option><option value="remote">Remote work and slow travel</option></select></label><label>Travellers<select name="people"><option>Solo</option><option>Couple</option><option>Family</option></select></label><label>Cooking style<select name="cook"><option value="inside">Inside kitchen</option><option value="outside">Mostly outside</option></select></label><label>Comfort priority<select name="comfort"><option value="shelter">Outdoor shelter</option><option value="lighting">Evenings outside</option><option value="light">Keep it simple</option></select></label><label>Interior palette<select name="theme">${Object.entries(INTERIOR_THEMES).map(([id,t])=>`<option value="${id}">${esc(t.name)}</option>`).join('')}</select></label><button class="btn">See my starting build ↗</button></form>`);$('#wizard-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget)),s=normalize({...defaults,model:v.travel==='weekend'&&v.cook==='outside'?'backpack':'basecamp',addons:[],interior:{theme:v.theme}},catalog),reasons=[];reasons.push(s.model==='backpack'?'Backpack is a simpler starting point for short trips with outdoor cooking.':'Basecamp is the starting point for a fitted living and kitchen space.');if(v.comfort==='shelter'){s.addons.push('awning');reasons.push('An awning adds sheltered outdoor space.')}if(v.comfort==='lighting'){s.addons.push('outdoorLights');reasons.push('Outdoor lighting makes evenings under the awning more comfortable.')}if(v.travel!=='weekend'){s.addons.push('extraSolar');reasons.push('Additional solar supplements the included 170W panel.')}if(v.cook==='inside'&&s.model==='backpack')s.addons.push('kitchen');setDraft(s);activeBuild=null;modal('Your suggested starting point',`<h2>${s.model==='basecamp'?'Basecamp':'Backpack'} · ${esc(INTERIOR_THEMES[v.theme].name)}</h2><ul>${reasons.map(x=>`<li>${x}</li>`).join('')}</ul><p class="notice">${v.people==='Family'?'Family sleeping and seating capacity must be confirmed with the team. ':''}These suggestions are illustrative. Fitment, load capacity and final equipment need specialist approval.</p><div class="record-price">${money(estimate(s,catalog).total)}</div>${btn('Customise this build','wizardDone')}`)};}
function floorPlan(){modal('Concept floor plan',`<div class="two-col"><div><h2>Make room for your way of living.</h2><p class="muted">Drag a furnishing or use its position fields. Snaps to 50 mm. Dimensions are provisional design references.</p><div id="floor-plan" class="floorplan" aria-label="Top-down concept floor plan"></div></div><div><div id="layout-fields"></div><p id="layout-result" class="notice">Concept room: 2.2 × 4.5 m. This is not a certified fitment drawing.</p><div class="actions">${btn('Inspect storage','storage','small secondary')}${btn('See cutaway','cutaway','small secondary')}${btn('Reset positions','resetLayout','small secondary')}</div></div></div>`);paintPlan();}
function paintPlan(){const plan=$('#floor-plan');if(!plan)return;plan.innerHTML=Object.keys(MOVABLE).filter(id=>interiorEnabled(draft,id)).map(id=>{const b=placement(draft,id);return `<button class="plan-item" data-block="${id}" style="left:${(b.x-b.w/2+1.1)/2.2*100}%;top:${(b.z-b.l/2+2.25)/4.5*100}%;width:${b.w/2.2*100}%;height:${b.l/4.5*100}%">${b.name}<small>${b.w} × ${b.l} m</small></button>`}).join('');$('#layout-fields').innerHTML=Object.keys(MOVABLE).map(id=>{const b=placement(draft,id);return `<div class="portal-card" style="padding:10px;margin-bottom:8px"><label><input type="checkbox" data-enable="${id}" ${interiorEnabled(draft,id)?'checked':''} ${id==='galleyCabinets'&&draft.model==='backpack'&&!draft.addons.includes('kitchen')?'disabled':''}> ${b.name}${id==='galleyCabinets'&&draft.model==='backpack'&&!draft.addons.includes('kitchen')?' · select the kitchen add-on first':''}</label><div class="form-row"><label>X · m<input class="portal-input" type="number" step=".05" data-position="${id}" data-axis="x" value="${b.x}"></label><label>Z · m<input class="portal-input" type="number" step=".05" data-position="${id}" data-axis="z" value="${b.z}"></label></div>${btn('Apply position','applyPosition:'+id,'small secondary')}</div>`}).join('');$$('[data-enable]').forEach(el=>el.onchange=()=>{const s=structuredClone(draft);s.interior.items[el.dataset.enable].enabled=el.checked;setDraft(s);paintPlan()});$$('[data-position]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('[data-act=\"applyPosition:'+el.dataset.position+'\"]').click()}});$$('[data-block]').forEach(el=>el.onpointerdown=e=>{e.preventDefault();const id=el.dataset.block,r=plan.getBoundingClientRect(),b=placement(draft,id),dx=e.clientX-(r.left+(b.x+1.1)/2.2*r.width),dy=e.clientY-(r.top+(b.z+2.25)/4.5*r.height);el.setPointerCapture(e.pointerId);el.onpointermove=v=>{const x=Math.round(((v.clientX-dx-r.left)/r.width*2.2-1.1)*20)/20,z=Math.round(((v.clientY-dy-r.top)/r.height*4.5-2.25)*20)/20;el.dataset.x=x;el.dataset.z=z;el.style.left=(x-b.w/2+1.1)/2.2*100+'%';el.style.top=(z-b.l/2+2.25)/4.5*100+'%'};el.onpointerup=()=>{el.onpointermove=null;move(id,{x:Number(el.dataset.x??b.x),z:Number(el.dataset.z??b.z)})}});function move(id,p){const result=validatePlacement(draft,id,p);$('#layout-result').textContent=result.message;if(result.ok){const s=structuredClone(draft);s.interior.placements[id]=result.point;setDraft(s)}paintPlan()}}
async function saveBuild(){requireAccount();modal('Save this escape',`<form id="save-form" class="portal-form"><h2>Give your build a name.</h2><label>Build name<input required maxlength="80" name="title" value="${esc(activeBuild?.title||'My Hilux escape')}"></label><label class="check-label"><input name="copy" type="checkbox"><span>Save as a separate build</span></label><button class="btn">Save configuration</button></form>`);$('#save-form').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.currentTarget)),update=activeBuild&&!b.copy;activeBuild=await api('/records'+(update?'/'+activeBuild.id:''),{method:update?'PATCH':'POST',body:{kind:'build',title:b.title,version:activeBuild?.version,data:configData()}});await refresh();close();if(view==='build')$('.build-name').textContent=activeBuild.title;toast('Build saved with its configuration and estimate')}catch(err){toast(err.message)}};}
const requests=new Map();function getSnapshots(){if(!frame)return Promise.resolve([]);return new Promise(resolve=>{const requestId=crypto.randomUUID();requests.set(requestId,resolve);send('CD_SNAPSHOT',{requestId});setTimeout(()=>{if(requests.has(requestId)){requests.delete(requestId);resolve([])}},3000)})}
async function createProposal(){requireAccount();snapshots=await getSnapshots();modal('Create a proposal',`<form id="proposal-form" class="portal-form"><h2>A build you can discuss.</h2><p class="muted">Freezes this configuration, current itemised pricing and available 3D snapshots. Future edits will create a separate proposal.</p><label>Proposal name<input name="title" maxlength="80" required value="${esc((activeBuild?.title||'Hilux escape')+' proposal')}"></label><p class="notice">Illustrative estimate. Excludes the base vehicle; final equipment, tax and delivery terms require approval.</p><button class="btn">Create immutable proposal</button></form>`);$('#proposal-form').onsubmit=async e=>{e.preventDefault();try{const title=new FormData(e.currentTarget).get('title'),r=await api('/records',{method:'POST',body:{kind:'proposal',title,data:{...configData(),snapshots,buildId:activeBuild?.id,revision:byKind('proposal').length+1}}});await refresh();showProposal(r)}catch(err){toast(err.message)}};}
function proposalHTML(r){const d=r.data,p=d.estimate||estimate(d.config,catalog);return `<div class="proposal"><p class="eyebrow">CAMPER DYNAMICS / CONFIGURATION PROPOSAL</p><h2>${esc(r.title)}</h2><p class="muted">${esc(r.id)} · Revision ${d.revision||r.version} · ${date(d.createdAt||r.created_at)}<br>Illustrative estimate · Vehicle excluded · Catalog revision ${d.catalogRevision||1}</p><div class="thumb-row">${(d.snapshots||[]).map(src=>`<img src="${esc(src)}" alt="Saved 3D configuration snapshot">`).join('')}</div><table class="portal-table"><thead><tr><th>Specification</th><th>Estimated price</th></tr></thead><tbody>${p.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${money(i.price)}</td></tr>`).join('')}<tr><td>Tax${catalog.taxRate?' (illustrative)':''}</td><td>${money(p.tax)}</td></tr><tr><th>Conversion estimate</th><th>${money(p.total)}</th></tr></tbody></table><h3>Interior configuration</h3><p>${esc(INTERIOR_THEMES[d.config.interior.theme].name)} · ${INTERIOR_FEATURES.filter(f=>interiorEnabled(d.config,f.id)).length} enabled furnishings. Custom placements and finishes are preserved in the configuration file.</p><details><summary>Full interior specification and floor plan</summary><pre style="white-space:pre-wrap;font:inherit;font-size:11px;line-height:1.7">${esc(interiorSummary(d.config))}\n${esc(Object.keys(d.config.interior.placements||{}).map(id=>{const p=d.config.interior.placements[id];return MOVABLE[id].name+': X '+p.x+' m, Z '+p.z+' m'}).join('\n'))}</pre></details><p class="notice">Final fitment, dimensions, payload, availability, tax, transport and delivery schedule require written confirmation. This snapshot does not place an order or reserve production.</p></div>`;}
function showProposal(r){modal('Saved proposal',proposalHTML(r)+`<div class="actions">${btn('Print / Save PDF','print:'+r.id)}${btn('Configuration file','proposalJSON:'+r.id,'secondary')}${btn('Reopen this build','open:'+r.id,'secondary')}${btn('Private share link','share:'+r.id,'secondary')}</div>`)}
function compare(){const rows=[...selected].map(recordById).filter(Boolean);if(rows.length<2)return toast('Select two or three saved builds');modal('Compare your escapes',`<label class="check-label"><input type="checkbox" id="only-diff"><span>Show differences only</span></label><div style="overflow:auto"><table class="portal-table" id="compare-table"></table></div>`);const values=r=>{const c=r.data.config,p=r.data.estimate||estimate(c,catalog);return {Model:c.model,Exterior:c.color,Wood:c.wood,Fabric:c.fabric,Theme:c.interior.theme,Finishes:JSON.stringify(c.interior.finishes),Styles:[c.interior.bedStyle,c.interior.tableShape,c.interior.curtainStyle,c.interior.cabinetStyle].join(', '),ItemColours:JSON.stringify(Object.fromEntries(Object.entries(c.interior.items).filter(([,x])=>x.color).map(([k,x])=>[k,x.color]))),Accessories:c.addons.map(id=>catalog.addons.find(a=>a.id===id)?.name||id).join(', '),Furnishings:INTERIOR_FEATURES.filter(f=>interiorEnabled(c,f.id)).map(x=>x.name).join(', '),Placements:JSON.stringify(c.interior.placements),Estimate:money(p.total)}};const paint=()=>{$('#compare-table').innerHTML=`<thead><tr><th>Specification</th>${rows.map(r=>`<th>${esc(r.title)}</th>`).join('')}</tr></thead><tbody>${Object.keys(values(rows[0])).filter(k=>!$('#only-diff').checked||new Set(rows.map(r=>values(r)[k])).size>1).map(k=>`<tr><th>${k}</th>${rows.map(r=>`<td>${esc(values(r)[k])}</td>`).join('')}</tr>`).join('')}</tbody>`};$('#only-diff').onchange=paint;paint();}
function history(id){const r=recordById(id);modal('Build revision history',`<h2>${esc(r.title)}</h2>${(r.data.history||[]).slice().reverse().map((h,i)=>`<div class="update"><p>Version ${h.version} · ${date(h.at)}</p>${btn('Open this revision','revision:'+id+':'+i,'small secondary')}</div>`).join('')||empty('The next saved edit will add a revision here.')}`)}
async function discussion(id){const r=recordById(id);modal('Build discussion',`<h2>${esc(r.title)}</h2>${workspace.records.filter(x=>x.kind==='comment'&&x.data.recordId===id).map(commentHTML).join('')||'<p class="muted">Add a component-specific question or revision request.</p>'}${commentForm()}`);$('#comment-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));await api('/comments',{method:'POST',body:{...data,recordId:id}});await refresh();discussion(id)};}
const commentHTML=r=>`<div class="comment"><span class="chip">${esc(r.data.component||'Overall build')}</span><p>${esc(r.data.text)}</p><small class="muted">${esc(r.data.author)} · ${date(r.created_at)}</small></div>`;
