async function share(id){requireAccount();const s=await api('/shares',{method:'POST',body:{recordId:id}}),url=location.origin+'/#share/'+s.token;modal('Private build link',`<h2>Bring someone into the conversation.</h2><label class="field">Link<input class="portal-input" readonly value="${esc(url)}"></label><p class="notice">Expires ${date(s.expiresAt)}. ${isPreview?'Device preview links work only in this browser storage.':'Recipients must sign in and have access to this private website. This does not grant website access.'}</p><div class="actions">${btn('Copy link','copy:'+url)}${btn('Revoke link','revoke:'+s.token,'danger')}</div>`);}
async function sharedPage(token){if(!session.user){$('#portal-view').innerHTML=empty('Sign in to view this private build.','<a class="btn" href="/signin-with-chatgpt?return_to='+encodeURIComponent('/#share/'+token)+'">Sign in</a>');return;}const s=await api('/share/'+token);$('#portal-view').innerHTML=`<div class="portal-container"><p class="eyebrow">PRIVATE BUILD DISCUSSION</p><h1>${esc(s.record.title)}</h1><p class="lead">${money((s.record.data.estimate||estimate(s.record.data.config,catalog)).total)} · Version ${s.record.version}</p><div class="actions">${btn('Explore configuration','sharedOpen')}</div><div class="two-col" style="margin-top:24px"><div>${s.comments.map(commentHTML).join('')||empty('No notes yet.')}</div><div class="portal-card">${commentForm()}</div></div></div>`;$('#comment-form').onsubmit=async e=>{e.preventDefault();await api('/share/'+token,{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});await sharedPage(token)};root.querySelector('[data-act=sharedOpen]').onclick=()=>{setDraft(s.record.data.config);activeBuild=null;go('build')};}
async function admin(){if(!session.admin){$('#portal-view').innerHTML=empty('This page is available to authorised team members.');return;}const settings=await api('/admin/settings'),tabs={enquiries:'Enquiries & builds',appointments:'Appointments',projects:'Projects',catalog:'Catalogue',availability:'Availability',promotion:'Trail offers',faq:'FAQ',audit:'Audit log'};let html='';if(adminTab==='enquiries')html=`<div class="actions" style="margin-bottom:20px">${btn('Export enquiries CSV','csv','secondary')}</div><div class="portal-grid">${workspace.records.filter(r=>['build','enquiry'].includes(r.kind)).map(r=>recordCard(r).replace('</article>',`<p class="record-meta">Account ${esc(r.user_id)}</p>${btn('Create customer project','createProject:'+r.id,'small secondary')}</article>`)).join('')||empty('Customer builds and enquiries appear here.')}</div>`;
 if(adminTab==='appointments')html=workspace.bookings.map(bookingCard).join('')||empty('No consultation requests.');
 if(adminTab==='projects')html=byKind('project').map(projectCard).join('')||empty('Create a project from an approved customer build.');
 if(adminTab==='catalog'){const c=settings.catalog;html=`<div class="portal-card"><h2>Catalogue publishing</h2><p class="muted">Edit draft pricing and compatibility. Preview the estimate, then publish. Existing proposals remain unchanged.</p><form id="catalog-form" class="portal-form"><table class="portal-table"><thead><tr><th>Item</th><th>Price · INR</th><th>Compatibility</th></tr></thead><tbody>${['models','addons','colors','woods','fabrics'].flatMap(group=>c[group].filter(i=>i.price!==null).map(i=>`<tr><td>${esc(i.name)}</td><td><input class="portal-input" required type="number" min="0" max="10000000" step="1" data-price="${group}:${i.id}" value="${i.price}"></td><td>${group==='addons'?['basecamp','backpack'].map(m=>`<label><input type="checkbox" data-compatible="${i.id}:${m}" ${i.models.includes(m)?'checked':''}> ${m}</label>`).join('<br>'):'—'}</td></tr>`)).join('')}</tbody></table><div id="catalog-preview" class="notice"></div><div class="actions">${btn('Preview draft estimate','previewCatalog','secondary')}<button class="btn" type="submit">Publish catalogue</button></div></form></div>`;}
 if(adminTab==='availability')html=`<div class="portal-card"><h2>Consultation availability</h2><form id="settings-form" class="portal-form"><label>Available weekdays (0 Sunday – 6 Saturday)<input name="days" value="${settings.availability.days.join(',')}"></label><label>Times · Asia/Kolkata<input name="times" value="${settings.availability.times.join(',')}"></label><label>Blocked dates · YYYY-MM-DD, comma separated<textarea name="blocked">${settings.availability.blocked.join(',')}</textarea></label><button class="btn">Publish availability</button></form></div>`;
 if(adminTab==='promotion'){const p=settings.promotion;html=`<div class="portal-card"><h2>Controlled trail offers</h2><p class="notice">No offer is enabled by default. Only publish terms approved by the business. Completion is checked in order and against minimum elapsed time. Offers have a usage cap and can be redeemed once per code.</p><form id="settings-form" class="portal-form"><label>Campaign identifier<input name="id" required value="${esc(p.id||'woodland-offer-1')}"></label><label>Offer label<input name="label" required maxlength="120" value="${esc(p.label||'')}"></label><label>Approved terms<textarea name="terms" required maxlength="2000">${esc(p.terms||'')}</textarea></label><label>Expiry<input type="date" name="expiry" required value="${p.expiresAt?.slice(0,10)||''}"></label><label>Total code limit<input type="number" name="maxUses" min="1" max="10000" required value="${p.maxUses||100}"></label><label class="check-label"><input type="checkbox" name="approved" ${p.approved?'checked':''}><span>These terms have business approval</span></label><label class="check-label"><input type="checkbox" name="active" ${p.active?'checked':''}><span>Activate this campaign</span></label><button class="btn">Publish offer settings</button></form></div>`;}
 if(adminTab==='faq')html=`<div class="portal-card"><h2>Additional landing-page FAQ</h2><form id="settings-form" class="portal-form"><label>One question and answer per line · Question | Answer<textarea name="faq" style="min-height:220px">${esc((settings.faq?.items||[]).map(x=>x.q+' | '+x.a).join('\n'))}</textarea></label><button class="btn">Publish FAQ</button></form></div>`;
 if(adminTab==='audit'){const logs=await api('/admin/audit');html=logs.map(r=>`<div class="portal-card" style="margin-bottom:10px"><h3>${esc(r.title)}</h3><p class="muted">${date(r.created_at)} · ${esc(r.user_id)}</p><details><summary>Recorded changes</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(r.data,null,2))}</pre></details></div>`).join('')||empty('Published catalogue and settings changes will be recorded here.');}
 $('#portal-view').innerHTML=`<div class="portal-container"><div class="page-heading"><div><p class="eyebrow">TEAM WORKSPACE${isPreview?' / DEVICE DEMO':''}</p><h1>Build the next chapter.</h1></div><a href="#profile" class="btn secondary">Customer workspace</a></div><div class="section-tabs">${Object.entries(tabs).map(([id,label])=>btn(label,'adminTab:'+id,id===adminTab?'small':'small secondary')).join('')}</div><div style="margin-top:24px">${html}</div></div>`;
 const draftCatalog=()=>{const c=structuredClone(settings.catalog);$$('[data-price]').forEach(el=>{const [g,id]=el.dataset.price.split(':');c[g].find(x=>x.id===id).price=Number(el.value)});c.addons.forEach(a=>{a.models=$$('[data-compatible]').filter(el=>el.checked&&el.dataset.compatible.startsWith(a.id+':')).map(el=>el.dataset.compatible.split(':')[1])});return c};
 if($('#catalog-form')){$('[data-act=previewCatalog]').onclick=()=>{try{const c=draftCatalog();$('#catalog-preview').textContent='Current configuration with draft pricing: '+money(estimate(draft,c).total)}catch(e){toast(e.message)}};$('#catalog-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/settings',{method:'PUT',body:{key:'catalog',value:draftCatalog()}});catalog=isPreview?draftCatalog():await api('/catalog');setDraft(draft);toast('Catalogue published; frozen proposals stay unchanged');await admin()}catch(err){toast(err.message)}};}
 if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));let value=b;if(adminTab==='availability')value={days:b.days.split(',').filter(Boolean).map(Number),times:b.times.split(',').map(x=>x.trim()).filter(Boolean),blocked:b.blocked.split(',').map(x=>x.trim()).filter(Boolean)};if(adminTab==='promotion')value={...b,maxUses:Number(b.maxUses),expiresAt:new Date(b.expiry+'T23:59:59+05:30').toISOString(),active:!!b.active,approved:!!b.approved};if(adminTab==='faq')value={items:b.faq.split('\n').filter(x=>x.trim()).map(x=>{const [q,...a]=x.split('|');return {q:q.trim(),a:a.join('|').trim()}})};try{await api('/admin/settings',{method:'PUT',body:{key:adminTab,value}});toast('Settings published and audit recorded');await admin()}catch(err){toast(err.message)}};
}
async function reschedule(id){const a=await api('/availability');modal('Reschedule consultation',`<form id="reschedule-form" class="portal-form"><label>New date<input name="day" type="date" required min="${new Date().toISOString().slice(0,10)}"></label><label>Time · Asia/Kolkata<select name="time">${a.times.map(t=>`<option>${t}</option>`).join('')}</select></label><p class="notice">Availability is checked when you submit. The revised appointment needs team confirmation.</p><button class="btn">Request new time</button></form>`);$('#reschedule-form').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.currentTarget));await api('/bookings/'+id,{method:'PATCH',body:{slot:new Date(v.day+'T'+v.time+':00+05:30').toISOString()}});await refresh();close();view==='admin'?admin():profile();toast('Reschedule request saved')}catch(err){toast(err.message)}};}
function calendar(id){const b=workspace.bookings.find(x=>x.id===id),start=new Date(b.data.slot),end=new Date(+start+3600000),fmt=d=>d.toISOString().replace(/[-:]/g,'').replace('.000','');download('camper-consultation.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Camper Dynamics//Consultation//EN','BEGIN:VEVENT','UID:'+b.id+'@camperdynamics','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:Camper Dynamics consultation ('+b.status+')','DESCRIPTION:Reference '+b.id.slice(0,8).toUpperCase()+'. Check Profile for confirmation and meeting details.','STATUS:'+ (b.status==='confirmed'?'CONFIRMED':'TENTATIVE'),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar');}
async function projectUpdate(id){const r=recordById(id);modal('Post project update',`<h2>${esc(r.title)}</h2><form id="project-form" class="portal-form"><label>Current stage<select name="stage">${['Requirements','Design approval','Production','Installation','Handover'].map(x=>`<option ${x===r.data.stage?'selected':''}>${x}</option>`).join('')}</select></label><label>Customer-visible update<textarea name="update" maxlength="2000"></textarea></label><label>Project images / documents<input name="files" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></label><p class="notice">Only post actual project progress. Choosing Design approval freezes the current linked build and estimate as a new design revision for the customer to review.</p><button class="btn">Post update</button></form>`);$('#project-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.currentTarget)),photos=[...(r.data.photos||[])];for(const f of e.currentTarget.elements.files.files){const fd=new FormData();fd.set('file',f);fd.set('projectId',id);photos.push((await api('/upload',{method:'POST',body:fd})).id)}await api('/records/'+id,{method:'PATCH',body:{version:r.version,data:{stage:data.stage,update:data.update,photos}}});await refresh();close();admin();toast('Project update posted')}catch(err){toast(err.message)}};}
function fileURL(id){return isPreview?recordById(id)?.data.url||'#':'/api/file/'+id}
root.addEventListener('click',async e=>{const target=e.target.closest('[data-act]');if(!target)return;const action=target.dataset.act,[key,id,arg]=action.split(':');try{
 if(key==='close')close();if(key==='wizard')wizard();if(key==='wizardDone'){close();go('build')}if(key==='chapter'){const section=$('.hero-story');window.scrollTo({top:section.offsetTop+(section.offsetHeight-innerHeight)*([0,.24,.50,.69,.84,.98][Number(id)]),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
 if(key==='undo')send('CD_UNDO');if(key==='redo')send('CD_REDO');if(key==='deployment'){deployed=!deployed;send('CD_DEPLOYMENT',{open:deployed});toast(deployed?'Camp setup opened':'Travel setup closed')}
 if(key==='applyPosition'){const x=Number($('[data-position="'+id+'"][data-axis=x]').value),z=Number($('[data-position="'+id+'"][data-axis=z]').value),r=validatePlacement(draft,id,{x,z});$('#layout-result').textContent=r.message;if(r.ok){const s=structuredClone(draft);s.interior.placements[id]=r.point;setDraft(s);paintPlan()}}if(key==='layout')floorPlan();if(key==='storage')send('CD_STORAGE');if(key==='cutaway'){send('CD_VIEW',{mode:'cutaway'});close()}if(key==='resetLayout'){const s=structuredClone(draft);s.interior.placements={};setDraft(s);paintPlan()}
 if(key==='save')await saveBuild();if(key==='proposal')await createProposal();if(key==='tab'){profileTab=id;profile()}if(key==='adminTab'){adminTab=id;await admin()}
 if(key==='new'){activeBuild=null;setDraft(defaults);go('build')}if(key==='open'){const r=recordById(id);setDraft(r.data.config);activeBuild=r.kind==='build'?r:null;close();go('build')}
 if(key==='viewProposal')showProposal(recordById(id));if(key==='proposalJSON')download('CamperDynamics-'+id+'.json',JSON.stringify(recordById(id),null,2));if(key==='print'){document.querySelector('#print-proposal')?.remove();const d=document.createElement('div');d.id='print-proposal';d.innerHTML=proposalHTML(recordById(id));d.querySelectorAll('details').forEach(el=>el.open=true);document.body.append(d);window.print()}
 if(key==='compare')compare();if(key==='history')history(id);if(key==='revision'){const r=recordById(id),h=r.data.history.slice().reverse()[Number(arg)];setDraft(h.config);activeBuild=r;close();go('build');toast('Historical configuration opened. Save to create a new revision.')}
 if(key==='discuss')await discussion(id);if(key==='share')await share(id);if(key==='copy'){await navigator.clipboard.writeText(action.slice(5));toast('Link copied')}if(key==='revoke'){await api('/share/'+id,{method:'DELETE'});close();toast('Share link revoked')}
 if(key==='export')download('CamperDynamics-workspace.json',JSON.stringify(workspace,null,2));if(key==='calendar')calendar(id);if(key==='reschedule')await reschedule(id);
 if(['cancel','confirm'].includes(key)){await api('/bookings/'+id,{method:'PATCH',body:{status:key==='cancel'?'cancelled':'confirmed'}});await refresh();view==='admin'?await admin():profile();toast(key==='cancel'?'Booking cancelled':'Appointment confirmed')}
 if(key==='bookingBuild'){const b=workspace.bookings.find(x=>x.id===id);setDraft(b.data.config);activeBuild=recordById(b.data.buildId)||null;go('build')}
 if(key==='createProject'){const r=recordById(id);modal('Create customer project',`<h2>${esc(r.title)}</h2><p class="notice">Create a tracked project only after the customer engagement is confirmed. This creates the Requirements stage; it does not imply production has started.</p>${btn('Create Requirements project','createProjectNow:'+id)}`)}
 if(key==='createProjectNow'){await api('/records',{method:'POST',body:{kind:'project',title:recordById(id).title+' project',data:{buildId:id}}});close();adminTab='projects';await refresh();await admin();toast('Customer project created')}
 if(key==='reviewDesign'){const r=recordById(id);modal('Design revision '+r.data.designRevision,proposalHTML({...r,data:r.data.design})+'<p class="notice">Frozen from linked build version '+r.data.design.buildVersion+'. Later build edits do not change this snapshot.</p>')}if(key==='projectUpdate')await projectUpdate(id);if(key==='approve'){const r=recordById(id);modal('Design approval',`<h2>Approve design revision ${r.data.designRevision}?</h2>${proposalHTML({...r,data:r.data.design})}<p class="notice">Your approval applies to this frozen design revision and linked build version ${r.data.design.buildVersion}.</p>${btn('Record my approval','approveNow:'+id)}`)}if(key==='approveNow'){const r=recordById(id);await api('/records/'+id,{method:'PATCH',body:{version:r.version,action:'approve',designRevision:r.data.designRevision}});await refresh();close();view==='admin'?await admin():profile();toast('Design approval recorded')}
 if(key==='redeem'){modal('Redeem approved offer',`<h2>${esc(id)}</h2><p class="notice">Redeeming marks this code used. Ask the team to apply the approved terms to your order before proceeding.</p>${btn('Mark code redeemed','redeemNow:'+id)}`)}if(key==='redeemNow'){await api('/rewards/redeem',{method:'POST',body:{code:id}});await refresh();close();profile();toast('Code redeemed')}
 if(key==='csv'){const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['Type','Reference','Name','Email','Status','Time','Estimate'],...workspace.bookings.map(b=>['Booking',b.id,b.data.name,b.data.email,b.status,b.data.slot,'']),...workspace.records.filter(r=>['build','enquiry'].includes(r.kind)).map(r=>[r.kind,r.id,r.title,r.user_id,'Saved',r.created_at,r.data.estimate?.total])];download('CamperDynamics-enquiries.csv',rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv')}
 }catch(err){toast(err.message)}
});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame?.contentWindow)return;const m=e.data||{};if(m.type==='CD_READY'){send('CD_CATALOG',{catalog});send('CD_LOAD',{config:draft,section:'exterior'});send('CD_QUALITY',{quality});if(view==='game')send('CD_GAME')}
 if(m.type==='CD_LOADED')studioReady=true;if(m.type==='CD_STATE'&&!studioReady)return;if(m.type==='CD_STATE'||m.type==='CD_LOADED'){draft=normalize(m.config,catalog);localStorage.setItem('cd-platform-draft',JSON.stringify(draft));$$('[data-act=undo]').forEach(b=>b.disabled=!m.undo);$$('[data-act=redo]').forEach(b=>b.disabled=!m.redo);clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>{if(!session.user)return;const data=configData();autosaveQueue=autosaveQueue.catch(()=>{}).then(async()=>{const body={kind:'draft',title:'Autosaved studio',version:draftRecord?.version,data};draftRecord=await api('/records'+(draftRecord?'/'+draftRecord.id:''),{method:draftRecord?'PATCH':'POST',body})});autosaveQueue.catch(err=>toast('Cloud autosave: '+err.message))},1800)}
 if(m.type==='CD_TOOL'){if(m.action==='layout')floorPlan();if(m.action==='wizard')wizard();if(m.action==='proposal')createProposal().catch(err=>toast(err.message));if(m.action==='deployment'){deployed=!deployed;send('CD_DEPLOYMENT',{open:deployed})}}if(m.type==='CD_QUALITY_CHANGE'&&['high','balanced','low'].includes(m.quality)){quality=m.quality;localStorage.setItem('cd-quality',quality);send('CD_QUALITY',{quality})}
 if(m.type==='CD_SAVE')saveBuild();if(m.type==='CD_SHARE'){if(activeBuild)share(activeBuild.id);else{toast('Save this build before creating a private link');saveBuild()}}if(m.type==='CD_COMPARE'){profileTab='builds';go('profile')}if(m.type==='CD_BOOK')go('book');if(m.type==='CD_SNAPSHOT_RESULT'){requests.get(m.requestId)?.(m.images||[]);requests.delete(m.requestId)}
 if(m.type==='CD_GAME_START'){gameRun=null;gameQueue=api('/game/start',{method:'POST',body:{config:draft}}).then(r=>gameRun=r).catch(err=>{toast('Trail saves require sign-in: '+err.message);gameRun=null})}
 if(m.type==='CD_GAME_CHECKPOINT')gameQueue=gameQueue.then(async()=>{if(!gameRun)return;const index=m.index??m.detail?.index,position=m.position??m.detail?.position;await api('/game/checkpoint',{method:'POST',body:{runId:gameRun.id,index,position}})}).catch(err=>{gameRun=null;toast('Trail validation: '+err.message)});
 if(m.type==='CD_GAME_FINISH')gameQueue=gameQueue.then(async()=>{if(!gameRun)return;const r=await api('/game/claim',{method:'POST',body:{runId:gameRun.id}});send('CD_REWARD',{offerCode:r.offer?.code||null});toast('Trail complete. Contact us to redeem your reward on your next order.')}).catch(err=>toast(err.message));
});
window.addEventListener('hashchange',render);
try{session=await api('/session');catalog=await api('/catalog');if(isPreview){const s=await api('/admin/settings');if(s.catalog)catalog=s.catalog;}if(session.user){await refresh();if(draftRecord&&!localStorage.getItem('cd-platform-draft'))draft=normalize(draftRecord.data.config,catalog)}}catch(e){toast('Workspace connection: '+e.message)}
render();
